Status SegmentImpl::dump() {
  if (sealed_) {
    return Status::NotSupported("Segment has been dumped.");
  }
  auto s = flush();
  CHECK_RETURN_STATUS(s);

  if (invert_indexers_) {
    s = invert_indexers_->seal();
    CHECK_RETURN_STATUS(s);
  }

  s = dump_fts_indexers();
  CHECK_RETURN_STATUS(s);

  sealed_ = true;

  return Status::OK();
}

